import csv, sys

fileheader = '''/*
 * This is an autogenerated file from https://github.com/wwuracingGH/ReprogrammingValues
 *
 * DO NOT EDIT.
 */

#include <stdint.h>

#define VERSION_NUMBER {0}
'''

topleveldefine = '''
/* Definitions for {1} [{0}], {5} */
#define PARAMPIPE_{1}_ID       {0}
#define PARAMPIPE_{1}_MINVALUE {3}
#define PARAMPIPE_{1}_MAXVALUE {4}
{2}* ParamPipe_{1} = 0;

'''

get_start = '''
/* returns the parameter cast to an integer */
int parampipe_getvalue(int id) {
\tswitch (id) {
'''

get_content = '''\tcase PARAMPIPE_{1}_ID:
\t\treturn (int)*ParamPipe_{1};
'''

get_end = '''\tcase 65535:
\t\treturn VERSION_NUMBER;
\t}
\treturn -1;
}

'''

set_start = '''
/* sets the parameter */
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wtype-limits"
void parampipe_setvalue(int id, int newval) {
\tswitch (id) {
'''

set_content = '''\tcase PARAMPIPE_{1}_ID:
\t\tif (({2})newval <= {4} && ({2})newval >= {3})
\t\t\t*ParamPipe_{1} = ({2})newval; 
\tbreak;
'''

set_end = '''\t}
}
#pragma GCC diagnostic pop
'''

infiles = ["nodes/vcu.csv", "nodes/pdb.csv", "nodes/halow.csv"]
outfiles = ["outputs/vcu_parampipe.c", "outputs/pdb_parampipe.c", "outputs/halow_parampipe.c"]

if __name__ == '__main__':
    version = sys.argv[1]
    print("version ", version)

    for infilepath, outfilepath in zip(infiles, outfiles):

        fp = open(infilepath)
        inreader = csv.reader(fp)
        incsv = []
        for row in inreader:
            incsv.append(row)
        fp.close()

        channels = incsv[0] 
        idx_id = next((i for i,c in enumerate(channels) if c == 'ID'), -1)
        idx_name = next((i for i,c in enumerate(channels) if c == 'Channel'), -1)
        idx_type = next((i for i,c in enumerate(channels) if c == 'Type'), -1)
        idx_min = next((i for i,c in enumerate(channels) if c == 'Minimum'), -1)
        idx_max = next((i for i,c in enumerate(channels) if c == 'Maximum'), -1)
        idx_hint = next((i for i,c in enumerate(channels) if c == 'Hint'), -1)

        with open(outfilepath, "w") as f:
            f.write(fileheader.format(version))

            for l in incsv[1:]:
                id, name, type, min, max, hint = l[idx_id], str(l[idx_name]).rstrip(), l[idx_type], l[idx_min], l[idx_max], l[idx_hint]
                f.write(topleveldefine.format(id, name, type, min, max, hint))

            f.write(get_start)

            for l in incsv[1:]:
                id, name, type, min, max, hint = l[idx_id], str(l[idx_name]).rstrip(), l[idx_type], l[idx_min], l[idx_max], l[idx_hint]
                f.write(get_content.format(id, name, type, min, max, hint))

            f.write(get_end)

            f.write(set_start)

            for l in incsv[1:]:
                id, name, type, min, max, hint = l[idx_id], str(l[idx_name]).rstrip(), l[idx_type], l[idx_min], l[idx_max], l[idx_hint]
                f.write(set_content.format(id, name, type, min, max, hint))

            f.write(set_end)
